import{_ as s,o as e,c as t,a6 as i}from"./chunks/framework.DMOj2-2K.js";const u=JSON.parse('{"title":"Install & first app","description":"","frontmatter":{},"headers":[],"relativePath":"guide/install.md","filePath":"guide/install.md"}'),n={name:"guide/install.md"};function l(p,a,d,h,o,r){return e(),t("div",null,[...a[0]||(a[0]=[i(`<h1 id="install-first-app" tabindex="-1">Install &amp; first app <a class="header-anchor" href="#install-first-app" aria-label="Permalink to &quot;Install &amp; first app&quot;">​</a></h1><p>You need <strong>Node.js 18 or newer</strong> (check with <code>node --version</code>). Cluub has no other dependencies.</p><h2 id="create-a-project" tabindex="-1">Create a project <a class="header-anchor" href="#create-a-project" aria-label="Permalink to &quot;Create a project&quot;">​</a></h2><p>Run one command in a terminal, just like <code>npm create vite</code> or <code>ng new</code>:</p><div class="vp-code-group vp-adaptive-theme"><div class="tabs"><input type="radio" name="group-pVqvm" id="tab-MD131j_" checked><label data-title="npm" for="tab-MD131j_">npm</label><input type="radio" name="group-pVqvm" id="tab-HXbWZQk"><label data-title="pnpm" for="tab-HXbWZQk">pnpm</label><input type="radio" name="group-pVqvm" id="tab-ysy65q9"><label data-title="yarn" for="tab-ysy65q9">yarn</label><input type="radio" name="group-pVqvm" id="tab-fvIrDlw"><label data-title="bun" for="tab-fvIrDlw">bun</label></div><div class="blocks"><div class="language-bash vp-adaptive-theme active"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> cluub@latest</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">pnpm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">yarn</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">bun</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> create</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span></code></pre></div></div></div><p>It asks for a project name and a template (or pass them: <code>npm create cluub@latest my-app -- --template ai-chat</code>), then prints the next steps:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">cd</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> install</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> run</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> dev</span></span></code></pre></div><p>Open <a href="http://localhost:3000" target="_blank" rel="noreferrer">http://localhost:3000</a>. You have a working full-stack todo app with a layout, an about page, validation, a JSON-file database, an AI summary button and tests. Edit <code>ui/pages/home.clb</code>, change the heading, save, and the browser reloads.</p><p>Every project has these scripts:</p><table tabindex="0"><thead><tr><th>Script</th><th>Runs</th><th>Does</th></tr></thead><tbody><tr><td><code>npm run dev</code></td><td><code>cluub dev</code></td><td>Build, run and reload on save</td></tr><tr><td><code>npm test</code></td><td><code>cluub test</code></td><td>Generate and run all tests</td></tr><tr><td><code>npm run check</code></td><td><code>cluub check</code></td><td>Errors and suggestions, without running</td></tr><tr><td><code>npm run build</code></td><td><code>cluub build</code></td><td>Compile to <code>dist/</code></td></tr><tr><td><code>npm start</code></td><td><code>cluub start</code></td><td>Run the built app</td></tr></tbody></table><h2 id="or-install-the-cluub-command-globally" tabindex="-1">Or install the <code>cluub</code> command globally <a class="header-anchor" href="#or-install-the-cluub-command-globally" aria-label="Permalink to &quot;Or install the \`cluub\` command globally&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">npm</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> install</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> -g</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> @cluub-lang/cluub</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> new</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">cd</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> my-app</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> dev</span></span></code></pre></div><p>With the global command you can skip <code>npm install</code> in each project; inside a project, <code>npx cluub …</code> also works.</p><p>Both packages are on npm: <a href="https://www.npmjs.com/package/@cluub-lang/cluub" target="_blank" rel="noreferrer"><code>@cluub-lang/cluub</code></a> (the compiler, runtime and <code>cluub</code> command) and <a href="https://www.npmjs.com/package/create-cluub" target="_blank" rel="noreferrer"><code>create-cluub</code></a> (used by <code>npm create cluub</code>).</p><div class="tip custom-block"><p class="custom-block-title">Working on Cluub itself</p><p>To try a local copy of the compiler, run <code>npm link</code> inside the <code>cluub</code> repository folder, then use <code>cluub new my-app</code>.</p></div><h2 id="templates" tabindex="-1">Templates <a class="header-anchor" href="#templates" aria-label="Permalink to &quot;Templates&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Template</th><th>What it gives you</th></tr></thead><tbody><tr><td><code>app</code> (default)</td><td>Full-stack todos: layout, components, file storage, AI summary, tests</td></tr><tr><td><code>ai-chat</code></td><td>A chat assistant with conversation memory and structured AI output</td></tr><tr><td><code>blank</code></td><td>The folder structure and one page</td></tr></tbody></table><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> new</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> support-bot</span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;"> --template</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> ai-chat</span></span></code></pre></div><h2 id="turning-on-ai" tabindex="-1">Turning on AI <a class="header-anchor" href="#turning-on-ai" aria-label="Permalink to &quot;Turning on AI&quot;">​</a></h2><p>Cluub is <strong>bring-your-own-key</strong>: it never provides or proxies an AI key. Add yours with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> ai</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> set</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> claude</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">      # or openai / gemini; the key is asked for privately</span></span>
<span class="line"><span style="--shiki-light:#953800;--shiki-dark:#FFA657;">cluub</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> ai</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> test</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;"> claude</span></span></code></pre></div><p>The rest of this section shows the <code>.env</code> file that command writes. To let your app&#39;s <em>users</em> bring their own keys instead, see <a href="/guide/ai-keys">Your own AI keys</a>.</p><h3 id="the-env-file" tabindex="-1">The .env file <a class="header-anchor" href="#the-env-file" aria-label="Permalink to &quot;The .env file&quot;">​</a></h3><p>Copy <code>.env.example</code> to <code>.env</code> and set <strong>one</strong> key:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light-default github-dark-default vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">ANTHROPIC_API_KEY</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">...</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">      # Claude</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;"># OPENAI_API_KEY=...</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;"># GEMINI_API_KEY=...</span></span>
<span class="line"><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;"># CLUUB_AI=ollama           # local models, no key needed</span></span></code></pre></div><h2 id="editor-support" tabindex="-1">Editor support <a class="header-anchor" href="#editor-support" aria-label="Permalink to &quot;Editor support&quot;">​</a></h2><p>Syntax highlighting is defined in <code>editors/cluub.tmLanguage.json</code> (TextMate format, works in VS Code, Sublime Text and others). A language server with inline errors and suggestions is on the <a href="/reference/roadmap">roadmap</a>. Until then, run <code>cluub dev</code>: it prints errors and suggestions on every save.</p>`,27)])])}const k=s(n,[["render",l]]);export{u as __pageData,k as default};
